#!/bin/bash
source ~/.bashrc
job_slot_to_gpu=(-1 2 3 4 5 6)

# Preflight
# env_parallel --eta -j 1 --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py -c job +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardExpectedSample steering.tilt={tilt} steering.penalization_power={penalization_power} model.conf={model_alt_id}' ::: $(duckdb runs.sqlite -c "copy (select * from SweepTrainedModel cross join SweepFKPotential cross join SweepFKEnsembleSize cross join SweepPenalizationPower) to '/dev/stdout'")
# env_parallel --eta -j 1 --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py -c job +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardSubEnsemblePushforward steering.intermediate_reward.sub_ensemble_size={sub_ensemble_size} steering.tilt={tilt} model.conf={model_alt_id}' ::: $(duckdb runs.sqlite -c "copy (select * from SweepTrainedModel cross join SweepFKPotential cross join SweepFKEnsembleSize cross join SweepFKSubEnsembleSize) to '/dev/stdout'")
# env_parallel --eta -j 1 --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py -c job +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardExpectedSample steering.tilt={tilt} steering.penalization_power=0 model.conf={model_alt_id}' ::: $(duckdb runs.sqlite -c "copy (select * exclude tilt, SweepTilt.tilt from SweepTrainedModel natural join BestFKParameter cross join SweepTilt where penalization_power = 0 order by dynamical_system desc, SweepTilt.tilt) to '/dev/stdout'")
# Go
env_parallel --delay 30 --eta -j $((${#job_slot_to_gpu[@]} - 1)) --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardExpectedSample steering.tilt={tilt} steering.penalization_power=0 model.conf={model_alt_id}' ::: $(duckdb runs.sqlite -c "copy (select * from SweepModelTrained cross join SweepFKPotential cross join SweepFKEnsembleSize) to '/dev/stdout'")
# env_parallel --delay 30 --eta -j $((${#job_slot_to_gpu[@]} - 1)) --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardSubEnsemblePushforward steering.intermediate_reward.sub_ensemble_size={sub_ensemble_size} steering.tilt={tilt} model.conf={model_alt_id}' ::: $(duckdb runs.sqlite -c "copy (select * from SweepTrainedModel cross join SweepFKPotential cross join SweepFKEnsembleSize cross join SweepFKSubEnsembleSize) to '/dev/stdout'")
# env_parallel --dry-run -j $((${#job_slot_to_gpu[@]} - 1)) --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardExpectedSample steering.tilt={tilt} steering.penalization_power=0 model.conf={model_alt_id}' ::: $(duckdb runs.sqlite -c "copy (select * exclude tilt, SweepTilt.tilt from SweepTrainedModel natural join BestFKParameter cross join SweepTilt where penalization_power = 0 order by dynamical_system desc, SweepTilt.tilt) to '/dev/stdout'")
# env_parallel --dry-run --line-buffer -j $((${#job_slot_to_gpu[@]} - 1)) --colsep , --header : CUDA_VISIBLE_DEVICES='${job_slot_to_gpu[{%}]}' 'python src/userfm/main.py +experiment=Steer{dynamical_system} steering=FeynmannKac steering.ensemble_size={ensemble_size} steering.potential={potential} steering/intermediate_reward=FeynmannKacIntermediateRewardExpectedSample steering.tilt={tilt} steering.penalization_power=0 model.conf={model_alt_id} dataset.time_step_count={time_step_count} log_constraint_values=true' ::: $(duckdb runs.sqlite -c "copy (select Conf.alt_id as model_alt_id, SweepTrajectoryLength.time_step_count, SweepModelTrained.tilt, BestFKParameter.* from Conf join TrainingAndEvaluation on Conf.id = TrainingAndEvaluation.id join Dataset on TrainingAndEvaluation.Dataset = Dataset.id join DynamicalSystem on Dataset.id = DynamicalSystem.id join SweepTrajectoryLength on (Dataset.sa_inheritance = SweepTrajectoryLength.dynamical_system and DynamicalSystem.time_step_count = SweepTrajectoryLength.time_step_count) join SweepModelTrained on (SweepTrajectoryLength.dynamical_system = SweepModelTrained.dynamical_system) join BestFKParameter on BestFKParameter.dynamical_system = SweepTrajectoryLength.dynamical_system where fit and penalization_power = 0) to '/dev/stdout'")
